#ifndef SIMULATION_H
#define SIMULATION_H

#include <bdExample/bdExampleCommon/bdExampleCommon.h>

#include <bdExample/bdExampleCommonLobby/bdExampleCommonLobby.h>
#include <bdLobby/bdLobbyCommon/bdLobbyServicesCommon.h>
#include <bdLobby/bdVoteRank/bdVoteRank.h>
#include <bdLobby/bdVoteRank/bdRatingInfo.h>
#include <bdLobby/bdVoteRank/bdVoteRankStatsInfo.h>
#include <bdLobby/bdContentStreaming/bdFileID.h>
#include <bdCore/bdCrypto/bdHashTiger192.h>

#define MAX_NUM_DISPLAY_RANKS (5u)

#define FILE_HASH_SIZE 24
#define FILE_PORTION_SIZE 1000
#define FILE_SIZE_HTTP (10*1000u) 
#define MAX_SLOTS_PER_USER 5

// Note: There will be a unique voterank leaderboardID per category in bdVoteRank.
// Category list creation will in future be handled in WebIMP, 
// and this #define list of LB_IDs and also the category enum (see ContentStreamingExample\Simulation.h)
// will be autogenerated by WebIMP when generating client code.
//
// Until then, studio's must provide to DemonWare a list of categories they wish to use.
// Demonware will then provide the LB_IDs #defines for use here, and also provide the enum below.
//
// bdLobby\bdVoteRank\bdVoteRankStatsInfo is the class for deserializing bdVoteRank leaderboards.
enum bdVoteRankCategoryLBID
{
	BD_VOTERANK_LB_ID_CATEGORY_PHOTO	= 23,
	BD_VOTERANK_LB_ID_CATEGORY_JPEG		= 24,
	BD_VOTERANK_LB_ID_CATEGORY_PNG		= 25,
	BD_VOTERANK_LB_ID_CATEGORY_MOVIE	= 26,
	BD_VOTERANK_LB_ID_CATEGORY_LIVERY	= 27,
	BD_VOTERANK_LB_ID_CATEGORY_GROUP	= 28,
	BD_VOTERANK_LB_ID_CATEGORY_CHALLENGE = 29
};

class Simulation : public bdDemo
{
	public:

		BD_DECLARE_NEW_AND_DELETE_OPERATORS

		Simulation();

		~Simulation();

		virtual bdBool init(bdInt argc,
							bdNChar8* argv[]);

		virtual bdBool step(const bdFloat32 time);
		
		virtual void quit();

	protected:

		enum Task
		{
			START_NETWORK,			
			CHECK_DNS,
			CREATE_ACCOUNT,			
			AUTHENTICATE_ACCOUNT,
			LOBBY_CONNECT,

			UPLOAD_FILE,

			// voterank tasks
			SUBMIT_RATING,
			GET_RATING,

			LOBBY_DISCONNECT,
			STOP_NETWORK
		};

		void startTask();
		void pumpTask();
		void displayTaskResult();

		// Network startup
		void startNetworkDescription(bdString& description);
		void startNetwork();
		void pumpStartNetwork();
#ifndef BD_PLATFORM_XENON
		// DNS lookup
		void checkDNSDescription(bdString& description);
		void startCheckDNS();
		void pumpCheckDNS();

		// Authentication service 	
		bdAuthService* getAuthService();
		const bdAuthInfo *getAuthInfo();
		void checkAuthServiceError();
		void pumpAuthServiceTask();

		// Create account
		void createAccountDescription(bdString& description);
		void startCreateAccount();
		void pumpCreateAccount();

		// Authenticate account
		void authenticateAccountDescription(bdString& description);
		void startAuthenticateAccount();
		void pumpAuthenticateAccount();
#endif
		// Lobby service connect
		void lobbyServiceConnectDescription(bdString& description);
		void startLobbyServiceConnect();
		void pumpLobbyServiceConnect();
		
		// upload file by http
		void generateUploadDescription(bdString& description);
		void startUpload();
		void pumpUpload();

		// submit rating
		void generateSubmitRatingDescription(bdString& description);
		void startSubmitRating();
		void pumpSubmitRating();
			
		// get Rating 
		void generateGetRatingDescription(bdString& description);
		void startGetRating();
		void pumpGetRating();
	
		// Lobby disconnect
		void lobbyServiceDisconnectDescription(bdString& description);
		void startLobbyServiceDisconnect();
		void pumpLobbyServiceDisconnect();

		// Network stop
		void stopNetworkDescription(bdString& description);
		void stopNetwork();


		
	protected:

		// receives log messages
		bdLogSubscriber m_logSubscriber;

		TaskStatus m_taskStatus;
		Task m_task;
		bdString m_lastTaskDescription;

		bdBool m_changedScreen;
		bdString m_screenText;

		bdInetAddr m_authAddr;
		bdGetHostByName *m_authGetHostByName;
#ifndef BD_PLATFORM_XENON
		bdAuthService *m_authService;
#endif
		bdLobbyService *m_lobbyService;

		bdInetAddr m_lsgAddr;
		bdGetHostByName *m_lsgGetHostByName;

		bdRemoteTaskRef m_remoteTask;

		bdBool m_pumpLobbyConnection;
		bdLobbyErrorCode m_lobbyErrorCode;

		bdOnlineUserID m_UserId;

		// ContentStreaming / upload related
		bdFileID m_uploadedFileID;
		bdNChar8 m_myFileNameHTTP[BD_MAX_FILE_NAME_LENGTH];
		bdUInt16 m_fileSizeIndex;
		bdUInt32 m_fileSize;
		bdUInt16 m_fileSlot;
		bdUByte8 *m_fileData;

#ifndef BD_PLATFORM_XENON
		bdHashTiger192 m_tigerHash;
		bdUByte8 m_hashFile[FILE_HASH_SIZE];
#else
		bdUByte8 m_filePortion[FILE_PORTION_SIZE];
#endif

		// An items category. Specified on upload.
		// Arbitrary integer value used to seperate and search for content.
		// Initially intended for specifying file type on upload.
		enum bdCategory
		{
			PHOTO = 0,
			JPEG,
			PNG,
			MOVIE,
			LIVERY,
			GROUP,
			CHALLENGE
		};

		bdCategory m_myCategory;
		bdString m_fileListString;

		//VoteRank specific data
		bdRatingInfo m_newRating[MAX_NUM_DISPLAY_RANKS];
		bdVoteRankStatsInfo m_voteRankStatsInfo[MAX_NUM_DISPLAY_RANKS];

};

#endif // SIMULATION_H
